  "summary": "The code suffered from significant performance bottlenecks due to O(n^2) string concatenation and lacked necessary security sanitization against CSV injection. Overall code health was improved by adding type hints, docstrings, and optimizing memory usage with list joins.",
  "fixed_code": "from typing import Iterable, Any, List\n\ndef sanitize(value: Any) -> str:\n    \"\"\"Sanitize cell values to prevent CSV injection.\"\"\"\n    s = str(value)\n    if s.startswith(('=', '+', '-', '@')):\n        return \"'\" + s\n    return s\n\ndef render_csv(header: List[str], rows: Iterable[Iterable[Any]]) -> str:\n    \"\"\"Renders a list of rows into a CSV formatted string.\"\"\"\n    lines = [','.join(sanitize(h) for h in header)]\n    for row in rows:\n        lines.append(','.join(sanitize(cell) for cell in row))\n    return '\\n'.join(lines) + '\\n'\n\ndef column_widths(header: List[str], rows: Iterable[Iterable[Any]]) -> List[int]:\n    \"\"\"Calculates the maximum width for each column.\"\"\"\n    widths = [len(h) for h in header]\n    for row in rows:\n        for i, c in enumerate(row):\n            widths[i] = max(widths[i], len(str(c)))\n    return widths"
